        if len(rows) == 0 or len(cols) == 0:
            continue

        sub = grid[:rows[-1] + 1, :cols[-1] + 1]
        if np.any(sub == bg):
            continue

        area = sub.shape[0] * sub.shape[1]
        if best is None or area > best[0]:
            best = (area, bg, sub)

    if best is None:
        sub = grid
    else:
        sub = best[2]

    ph, pw = sub.shape

    row_period = ph
    for p in range(1, ph + 1):
