    def comps(mask):
        seen = np.zeros(mask.shape, dtype=bool)
        res = []
        for r in range(mask.shape[0]):
            for c in range(mask.shape[1]):
                if mask[r, c] and not seen[r, c]:
                    stack = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    while stack:
                        x, y = stack.pop()
                        cells.append((x, y))
                        for dx in (-1, 0, 1):
                            for dy in (-1, 0, 1):
                                if dx == 0 and dy == 0:
                                    continue
                                nx, ny = x + dx, y + dy
                                if 0 <= nx < mask.shape[0] and 0 <= ny < mask.shape[1] and mask[nx, ny] and not seen[nx, ny]:
                                    seen[nx, ny] = True
                                    stack.append((nx, ny))
                    res.append(cells)
        return res

    ones = comps(grid == 1)
    if not ones:
        return out

    colored = comps((grid != 0) & (grid != 1))
    if not colored:
        return out

    key = None
    for comp in colored:
        vals = {grid[r, c] for r, c in comp}
        if len(vals) > 1:
            key = comp
            break
    if key is None:
        key = max(colored, key=len)

    kr0 = min(r for r, c in key)
    kc0 = min(c for r, c in key)
    color_by_pos = {(r - kr0, c - kc0): grid[r, c] for r, c in key}

    obj_info = []
    for obj in ones:
        r0 = min(r for r, c in obj)
        c0 = min(c for r, c in obj)
        obj_info.append((r0, c0, obj))

    row_starts = sorted(set(r0 for r0, c0, obj in obj_info))
    col_starts = sorted(set(c0 for r0, c0, obj in obj_info))
    row_map = {r: i for i, r in enumerate(row_starts)}
    col_map = {c: i for i, c in enumerate(col_starts)}

    for r0, c0, obj in obj_info:
        pos = (row_map[r0], col_map[c0])
        if pos in color_by_pos:
            rr, cc = zip(*obj)
            out[rr, cc] = color_by_pos[pos]

    return out

