            if dr == 0 and not center_ok.get(cur, True):
                continue

            if dr != 0 and c - 1 >= 0 and blockers[rr, c - 1]:
                left = (rr, c - 1)
                if left not in parent or parent.get(cur) == left:
                    continue

            c0 = max(0, c - 1)
            c1 = min(w - 1, c + 1)
            if dr == 0 and right_gate(r, c):
                c1 = min(c1, c)

            for cc in range(c0, c1 + 1):
                if blockers[rr, cc]:
                    add_blocker(rr, cc, cur, True)
                else:
                    out[rr, cc] = 1

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    seen = np.zeros((h, w), dtype=bool)
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r, c] == 0 or seen[r, c]:
                continue

            color = grid[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []

            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == color:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((min(rs), max(rs), min(cs), max(cs), color))

    add = []
    remove = []

    for i in range(len(boxes)):
        r1a, r2a, c1a, c2a, col_a = boxes[i]
        for j in range(i + 1, len(boxes)):
            r1b, r2b, c1b, c2b, col_b = boxes[j]
            if col_a != col_b:
                continue

            color = col_a

            if c2a < c1b or c2b < c1a:
                if c2a < c1b:
                    left = (r1a, r2a, c1a, c2a)
                    right = (r1b, r2b, c1b, c2b)
                else:
                    left = (r1b, r2b, c1b, c2b)
                    right = (r1a, r2a, c1a, c2a)

                ot = max(left[0], right[0])
                ob = min(left[1], right[1])
                overlap = ob - ot + 1
                gap = right[2] - left[3] - 1

                if overlap >= 3 and gap <= overlap:
                    a = ot + 1
                    b = ob - 1
                    for cc in range(left[3], right[2] + 1):
                        add.append((a, cc, color))
                        add.append((b, cc, color))
                    for rr in range(a + 1, b):
                        remove.append((rr, left[3]))
                        remove.append((rr, right[2]))

            if r2a < r1b or r2b < r1a:
                if r2a < r1b:
                    top = (r1a, r2a, c1a, c2a)
                    bottom = (r1b, r2b, c1b, c2b)
                else:
                    top = (r1b, r2b, c1b, c2b)
                    bottom = (r1a, r2a, c1a, c2a)

                ol = max(top[2], bottom[2])
                orr = min(top[3], bottom[3])
                overlap = orr - ol + 1
                gap = bottom[0] - top[1] - 1

                if overlap >= 3 and gap <= overlap:
                    a = ol + 1
                    b = orr - 1
                    for rr in range(top[1], bottom[0] + 1):
                        add.append((rr, a, color))
                        add.append((rr, b, color))
                    for cc in range(a + 1, b):
                        remove.append((top[1], cc))
                        remove.append((bottom[0], cc))

    for r, c in remove:
        out[r, c] = 0

    for r, c, color in add:
        out[r, c] = color

    return out

def transform(grid):
    return np.vstack([
        np.tile(grid, (1, 3)),
        np.tile(np.fliplr(grid), (1, 3)),
        np.tile(grid, (1, 3)),
    ])
